import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';

export interface Notification {
  id: number;
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  duration?: number;
  'fade-out'?: boolean;
}

@Injectable({
  providedIn: 'root'
})
export class NotificationService {
  private notifications$ = new Subject<Notification>();
  private currentId = 0;

  getNotifications() {
    return this.notifications$.asObservable();
  }

  showSuccess(message: string, duration: number = 5000) {
    this.showNotification(message, 'success', duration);
  }

  showError(message: string, duration: number = 5000) {
    this.showNotification(message, 'error', duration);
  }

  showWarning(message: string, duration: number = 5000) {
    this.showNotification(message, 'warning', duration);
  }

  showInfo(message: string, duration: number = 5000) {
    this.showNotification(message, 'info', duration);
  }

  private showNotification(message: string, type: 'success' | 'error' | 'warning' | 'info', duration: number) {
    console.log('=== CRIANDO NOTIFICAÇÃO ===');
    console.log('Message:', message);
    console.log('Type:', type);
    console.log('Duration:', duration);

    const notification: Notification = {
      id: ++this.currentId,
      message,
      type,
      duration
    };

    console.log('Notification object:', notification);
    console.log('Enviando para Subject...');

    this.notifications$.next(notification);
    console.log('Notificação enviada para Subject!');
  }
}
